const payCost = (c, cost) => { for (const [k, v] of Object.entries(cost)) c[k] -= v; };
const costStr = (cost) => Object.entries(cost).map(([k, v]) => (k === 'coin' ? `${fmtN(v)}c` : `${v} ${MATN[k]}`)).join(' + ');
